// The built-in opening library (js/opening-library.js) and the names it leans on.
//
// The library is generated by tools/build-opening-library.mjs. Opening names in
// js/openings-eco.js are the keys the Opening ELO is stored under, and the app
// deletes the rating of any name that is no longer there, so this file also
// pins the names that existed before the library (v192).
//
// Run: npm run test:tree
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { Chess } from '../../vendor/chess.js';
import { VALID_OPENING_NAMES, classifyOpening } from '../../js/openings-eco.js';
import { OPENING_LIBRARY, LIBRARY_KEYS } from '../../js/opening-library.js';
import { buildLibrarySource } from '../../tools/build-opening-library.mjs';

const NAMES_V192 = JSON.parse(fs.readFileSync(new URL('./opening-names-v192.json', import.meta.url), 'utf8'));
const allLines = OPENING_LIBRARY.flatMap(g => g.lines.map(l => ({ group: g.name, eco: l[0], variation: l[1], moves: l[2].split(' '), key: l[3] })));

test('opening names: every name that existed at v192 is still there', () => {
  assert.equal(NAMES_V192.length, 115);
  const gone = NAMES_V192.filter(n => !VALID_OPENING_NAMES.has(n));
  assert.deepEqual(gone, []);
});

test('opening library: every line is legal chess from the starting position', () => {
  for (const l of allLines) {
    const game = new Chess();
    for (const san of l.moves) {
      let mv = null;
      try { mv = game.move(san); } catch { mv = null; }
      assert.ok(mv, `${l.group}: ${l.variation} — illegal ${san} in ${l.moves.join(' ')}`);
      assert.equal(mv.san, san, `${l.group}: ${l.variation} — ${san} is not how the board writes it`);
    }
  }
});

test('opening library: every key is an existing opening name, the one the trainer would credit', () => {
  for (const k of LIBRARY_KEYS) assert.ok(VALID_OPENING_NAMES.has(k), `${k} is not an opening name`);
  for (const l of allLines) {
    const name = classifyOpening(l.moves) || null;
    const key = l.key < 0 ? null : LIBRARY_KEYS[l.key];
    assert.equal(key, name, `${l.group}: ${l.variation}`);
  }
});

test('opening library: only the odd first moves the app cannot name have no key', () => {
  const without = allLines.filter(l => l.key < 0);
  assert.ok(without.length < 60, `${without.length} lines without a key`);
  for (const l of without) assert.ok(!classifyOpening([l.moves[0]]), `${l.group}: ${l.variation} has no key`);
  for (const first of ['e4', 'd4', 'c4', 'Nf3']) assert.ok(!without.some(l => l.moves[0] === first), first);
});

test('opening library: shape — unique openings, no repeated line, a side, sane sizes', () => {
  const names = OPENING_LIBRARY.map(g => g.name);
  assert.equal(new Set(names).size, names.length);
  assert.ok(names.length >= 140 && allLines.length >= 3500, `${names.length} openings, ${allLines.length} lines`);
  const ids = allLines.map(l => l.group + '|' + l.variation + '|' + l.moves.join(' '));
  assert.equal(new Set(ids).size, ids.length);
  for (const g of OPENING_LIBRARY) {
    assert.ok(g.side === 'w' || g.side === 'b', g.name);
    assert.ok(g.lines.length > 0, g.name);
  }
  for (const l of allLines) {
    assert.ok(l.moves.length >= 1 && l.moves.length <= 40, `${l.group}: ${l.variation}`);
    assert.match(l.eco, /^[A-E][0-9][0-9]$/);
  }
});

test('opening library: the file on disk is exactly what the tool writes', () => {
  const disk = fs.readFileSync(new URL('../../js/opening-library.js', import.meta.url), 'utf8').replaceAll('\r\n', '\n');
  assert.equal(disk, buildLibrarySource());
});
